from pathlib import Path
import sys
sys.path.insert(0,str(Path(__file__).resolve().parent.parent))
from rendu import outils

base,p,c,h,w,table,liste,save=outils(2,1)
t=p('Le Royal College of Physicians, dans son guide diagnostique britannique de 2022, définit la fibromyalgie comme un syndrome associant une douleur persistante et étendue à une fatigue intrusive, des troubles du sommeil, une altération des fonctions cognitives et physiques et une détresse psychologique. Cette définition décrit un ensemble clinique ; elle ne réduit donc pas la maladie à une douleur des muscles.','f83-rcp-definition','f83-rcp-bib')
t+=p('La Ligue suisse contre le rhumatisme emploie également le terme « syndrome de fibromyalgie » dans sa publication de janvier 2023. Elle souligne que le tableau dépasse les muscles, tendons et fascias et comprend notamment sommeil, fatigue et concentration.','f83-ligue-definition','f83-ligue-bib')
t+=h('Une douleur nociplastique exige une explication positive')
t+=p('La HAS, dans sa recommandation validée en juin 2025, rattache la fibromyalgie à une modification de la détection et de la modulation de la douleur dans le système nerveux central. Le diagnostic est clinique, car aucun biomarqueur spécifique ne permet actuellement de le confirmer.','f83-has-messages','f83-has-bib')
f=w('Nociplasticité : sens et limites',[
('Une douleur nociplastique correspond à une altération fonctionnelle de la nociception, sans argument pour une lésion tissulaire activant les nocicepteurs ni pour une lésion du système somatosensoriel expliquant cette douleur. Cette catégorie décrit un mécanisme de douleur ; elle ne signifie pas que la douleur est imaginaire.',['f83-has-orientation','f83-rcp-mecanismes']),
('Une douleur nociceptive résulte de l’activation des nocicepteurs, notamment lors d’une inflammation, tandis qu’une douleur neuropathique suppose une lésion ou une maladie somatosensorielle. Plusieurs mécanismes peuvent coexister chez une même personne ; une fibromyalgie ne dispense donc pas d’identifier une arthrite ou une neuropathie associée.',['f83-has-orientation','f83-has-depistage'])])
t+=p('Le clinicien explique le mécanisme dominant avec le vocabulaire '+f+' et relie cette explication aux symptômes vécus. Il évite ainsi de présenter la normalité des examens usuels comme une réfutation de la plainte.','f83-has-annonce','f83-rcp-mecanismes')
t+=h('Les mots ne doivent pas inventer une inflammation')
t+=p('Les anciennes appellations « fibrosite » et « fibromyosite » suggèrent à tort une inflammation musculaire causale. Le RCP les considère comme inexactes, parce que le mécanisme prédominant concerne le traitement de la douleur dans le système nerveux.','f83-rcp-definition','f83-rcp-mecanismes')
t+=p('Le syndrome ne correspond pas à une somatisation, à une mauvaise adaptation au stress ni à une insuffisance de volonté. Le RCP précise également que le déconditionnement et le manque de forme physique ne constituent pas sa définition causale ; une limitation d’activité peut toutefois faire partie du retentissement à traiter.','f83-rcp-mecanismes','f83-has-evaluation')
t+=table(['Notion','Ce que le clinicien retient','Conséquence'],[
['Fibromyalgie',p('La douleur généralisée s’accompagne de symptômes de fatigue, sommeil et cognition.','f83-rcp-definition'),p('Le clinicien évalue le retentissement global et applique des critères positifs.','f83-rcp-criteres-cadre')],
['Syndrome douloureux myofascial',p('Un point gâchette au sein d’une bande tendue peut provoquer douleur locale, réponse contractile et douleur référée.','p83-myofascial-fibro'),p('Une douleur provoquée localement ne suffit pas à établir les critères d’une fibromyalgie.','p83-myofascial-fibro','f83-rcp-criteres')],
['Myopathie',p('Une parésie, une atrophie ou une élévation de CK conduit à rechercher une affection musculaire.','p83-myofascial-fibro'),p('Le clinicien ouvre une démarche neuromusculaire plutôt que d’attribuer automatiquement ces anomalies au syndrome douloureux.','p83-myofascial-fibro','f83-has-depistage')],
['Douleur chronique étendue sous le seuil',p('Les symptômes peuvent rester proches des seuils sans satisfaire les critères de fibromyalgie.','f83-rcp-fluctuation'),p('Une hypothèse de travail et une réévaluation évitent à la fois le surdiagnostic et l’abandon des soins.','f83-rcp-fluctuation')]])
t+=p('Une maladie inflammatoire, une dépression ou une autre affection peut coexister avec la fibromyalgie. Le diagnostic ne repose donc ni sur l’exclusion exhaustive de toute maladie ni sur l’idée qu’une comorbidité rendrait le syndrome impossible.','f83-rcp-coexistence','f83-has-depistage')
save(t)

base,p,c,h,w,table,liste,save=outils(2,2)
t=p('La DGN qualifie la fibromyalgie de forme la plus fréquente de douleur musculaire généralisée dans sa recommandation diagnostique de 2025. Cette proposition concerne une présentation généralisée ; elle ne démontre aucun classement universel entre toutes les causes de myalgies localisées, post-traumatiques, infectieuses ou médicamenteuses.','p83-myofascial-fibro','dgn83-bib')
t+=h('Le cadre géographique accompagne chaque nombre')
t+=p('La publication suisse de la Ligue rapporte une prévalence mondiale de 2 à 4 % et décrit une atteinte surtout chez l’adulte jeune ou d’âge moyen. Ce chiffre mondial ne devient pas une prévalence suisse par le seul fait que la source est suisse.','f83-ligue-epidemiologie','f83-ligue-bib')
t+=p('La HAS rapporte une estimation de 1,5 à 2 % en population générale, avec une fréquence presque trois fois supérieure chez les femmes. Le passage consulté ne définit pas une cohorte suisse ; cette estimation européenne de synthèse ne mesure pas non plus la proportion de fibromyalgies parmi les personnes consultant pour myalgies.','f83-has-messages')
t+=table(['Estimation','Population et source','Usage permis et limite'],[
['2 à 4 %',p('La Ligue suisse cite la population mondiale dans son document de janvier 2023.','f83-ligue-epidemiologie','f83-ligue-bib'),p('L’estimation situe l’ampleur du syndrome ; elle ne constitue pas un taux national suisse.','f83-ligue-epidemiologie')],
['Deux à cinq fois',p('La Ligue décrit une fréquence féminine supérieure à celle des hommes.','f83-ligue-epidemiologie'),p('Le clinicien conserve la possibilité du diagnostic chez un homme ou chez un enfant, car la source ne limite pas la maladie aux femmes adultes.','f83-ligue-epidemiologie')],
['1,5 à 2 %',p('La HAS publie cette estimation en population générale dans sa recommandation validée en juin 2025.','f83-has-messages','f83-has-bib'),p('Cette estimation et celle de la Ligue ne sont pas additionnées ; leurs populations et méthodes ne sont pas interchangeables.','f83-has-messages','f83-ligue-epidemiologie')],
['Presque trois fois',p('La HAS rapporte cette différence entre femmes et hommes.','f83-has-messages'),p('Le sexe oriente la probabilité préalable mais ne remplace aucun critère positif.','f83-has-messages','f83-rcp-criteres')]])
t+=p('Le paquet consulté ne fournit pas une incidence annuelle suisse validée ni un taux de mortalité suisse ou européen suffisamment documenté pour être reproduit ici. Ces champs restent donc des limites explicites ; ni la prévalence mondiale ni un risque associé au syndrome ne permettent d’inventer une incidence ou une létalité.','f83-ligue-epidemiologie','f83-has-messages')
t+=h('Les groupes exposés ne constituent pas des exclusions')
t+=p('La Ligue décrit une fibromyalgie plus fréquente chez les personnes ayant un rhumatisme inflammatoire que dans la population moyenne. Ainsi, une polyarthrite n’oblige pas à choisir entre inflammation et fibromyalgie : chaque composante doit être évaluée et traitée selon ses propres arguments.','f83-ligue-epidemiologie','f83-has-depistage')
t+=p('Le RCP rapporte une augmentation du risque après des événements de vie stressants ou des traumatismes physiques ou psychologiques importants. Cependant, beaucoup de patients n’identifient aucun tel événement ; son absence ne réfute donc pas le diagnostic et sa présence ne prouve pas une cause psychologique exclusive.','f83-rcp-mecanismes','f83-rcp-bps')
t+=p('Une agrégation familiale est décrite, mais elle ne fournit pas un test génétique diagnostique dans la démarche recommandée. Le diagnostic demeure clinique et s’appuie sur le tableau, les critères et la recherche ciblée des maladies concomitantes.','f83-rcp-bps','f83-rcp-criteres','f83-has-depistage')
t+=h('Une évolution fluctuante impose un suivi fonctionnel')
t+=p('Le RCP souligne que la localisation et l’intensité peuvent varier, y compris autour du seuil diagnostique. Une fluctuation ne prouve ni une simulation ni une progression systématique ; les symptômes proches du seuil ne conduisent pas toujours vers une fibromyalgie constituée.','f83-rcp-fluctuation')
t+=p('La charge de santé publique tient aussi à la réduction des capacités physiques, aux activités quotidiennes et à la qualité de vie. La HAS recommande donc de suivre le fonctionnement, l’humeur, la vie familiale et professionnelle, plutôt que de limiter la surveillance à une note de douleur.','f83-has-messages','f83-has-suivi')
t+=p('L’isolement social est un risque souligné par la Ligue suisse. Le maintien de relations choisies et l’accès à des groupes d’entraide ou à une association de patients constituent des ressources concrètes, sans garantie de disparition des symptômes.','f83-ligue-relations')
save(t)

base,p,c,h,w,table,liste,save=outils(2,3)
t=p('Le modèle physiopathologique reste incomplet : le RCP décrit surtout une altération du traitement de la douleur, tandis que la DGN rappelle que les mécanismes et les biomarqueurs ne permettent pas un diagnostic biologique. Le cours distingue donc un mécanisme plausible, une observation de recherche et un test utilisable chez un patient.','f83-rcp-mecanismes','p83-myofascial-fibro')
t+=h('Amorce : des facteurs hétérogènes convergent vers la sensibilité')
t+=p('Des événements physiques ou psychologiques stressants peuvent augmenter le risque, et une susceptibilité familiale est possible. Toutefois, aucun déclencheur unique n’est nécessaire ; le clinicien ne transforme pas une histoire de stress en preuve de causalité ni en condition du diagnostic.','f83-rcp-mecanismes','f83-rcp-bps')
t+=p('Les interactions biologiques, psychologiques et sociales modifient l’expérience douloureuse. Le RCP distingue la nociception, traitement neuronal de stimuli potentiellement nocifs, de la douleur comme expérience consciente ; cette distinction permet de comprendre qu’une douleur importante ne mesure pas directement une lésion musculaire.','f83-rcp-bps')
t+=h('Développement cellulaire et réseaux : une hypothèse explicite')
t+=p('Des travaux sur le système nerveux périphérique décrivent, dans certains groupes, une signalisation électrique anormale de petites fibres et une réduction de leur densité cutanée. Le RCP mentionne aussi des effets immunitaires possibles, mais souligne le faible nombre d’études disponibles ; ces observations ne constituent pas une anomalie obligatoire chez tous les patients.','f83-rcp-mecanismes')
t+=p('La Ligue suisse indique également que le sens causal des anomalies de petites fibres demeure discuté. Une biopsie cutanée anormale chez une personne donnée ne peut donc pas être présentée comme la preuve que toute fibromyalgie est une neuropathie des petites fibres.','f83-ligue-mecanismes','p83-myofascial-fibro')
f=w('Sensibilisation : de la stimulation à la douleur',[
('La sensibilisation décrit une hypersensibilité des systèmes périphériques ou centraux à des stimulations externes. Une pression habituellement innocente peut devenir douloureuse ; les études fonctionnelles montrent alors davantage d’activité cérébrale liée à la douleur à ce seuil de pression.',['f83-rcp-mecanismes']),
('Ces résultats d’imagerie fonctionnelle sont des observations de recherche. La DGN précise que les anomalies de sensibilisation et de nocicepteurs observées dans des sous-groupes ne peuvent pas servir de biomarqueurs diagnostiques de la fibromyalgie.',['p83-myofascial-fibro'])])
t+=p('Au niveau des réseaux, le modèle de '+f+' relie une stimulation à une réponse douloureuse amplifiée. Il fournit une explication clinique de la sensibilité diffuse sans autoriser une IRM cérébrale systématique pour « montrer » la fibromyalgie.','f83-rcp-mecanismes','p83-myofascial-fibro','f83-rcp-differentiel')
t+=h('Installation clinique : un syndrome dépassant le muscle')
t+=p('La douleur devient étendue et s’associe à une fatigue intrusive, à un sommeil non réparateur et à des difficultés de concentration ou de mémoire. Le clinicien recherche ces dimensions ensemble, parce qu’une plainte régionale initiale peut masquer une douleur dans d’autres parties du corps.','f83-rcp-definition','f83-rcp-symptomes')
t+=p('L’hypersensibilité peut concerner le toucher, la pression, la température, la lumière ou le bruit. La HAS distingue cette hypersensibilité d’un déficit moteur ou sensitif systématisé et d’un gonflement articulaire objectivable, qui orientent vers une autre composante diagnostique.','f83-has-orientation')
t+=h('Maintien : des boucles cliniques modifiables')
t+=p('Une douleur persistante peut limiter les activités, perturber le sommeil et altérer les relations ou le travail. Les troubles de l’humeur et l’insomnie peuvent compliquer l’engagement dans les soins ; leur traitement vise le fonctionnement et ne signifie pas que la plainte initiale est psychologique.','f83-has-evaluation','f83-has-humeur','f83-has-suivi')
t+=p('Le déconditionnement ne définit pas la cause de la fibromyalgie selon le RCP. En revanche, une baisse d’activité et des comportements sédentaires peuvent apparaître dans son retentissement ; une activité progressive adaptée traite cette limitation sans prétendre réparer une lésion musculaire démontrée.','f83-rcp-mecanismes','f83-has-evaluation','f83-has-activite')
t+=table(['Perturbation ou observation','Exploration pertinente','Réponse thérapeutique et limite du mécanisme'],[
['Modulation douloureuse centrale',p('Le clinicien documente la distribution, la durée et les symptômes associés ; aucun marqueur spécifique ne confirme le mécanisme.','f83-has-messages','f83-rcp-criteres'),p('L’éducation et l’activité physique progressive constituent le socle ; l’exercice bénéficie de la recommandation forte EULAR.','f83-eular-strategie','f83-eular-exercice')],
['Petites fibres dans des sous-groupes',p('Une suspicion clinique de neuropathie justifie une exploration spécialisée ciblée ; une biopsie n’est pas un critère général de fibromyalgie.','p83-myofascial-fibro','f83-has-depistage'),p('Le clinicien traite une neuropathie démontrée selon son diagnostic et ne généralise pas cette anomalie à tout syndrome douloureux.','f83-has-depistage','p83-myofascial-fibro')],
['Douleur, fatigue et activité réduite',p('L’évaluation fonctionnelle porte sur mobilité, force, équilibre, capacités aérobies et fatigabilité avant un programme adapté.','f83-has-programme'),p('Les exercices de faible à moyenne intensité sont progressifs et ajustés à la tolérance, avec apprentissage de l’autonomie.','f83-has-programme','f83-has-relais')],
['Sommeil non réparateur',p('Le clinicien explore les habitudes et recherche notamment apnées et jambes sans repos.','f83-has-sommeil'),p('Une affection du sommeil reconnue reçoit un traitement spécifique ; une simple sédation ne corrige pas nécessairement sa cause.','f83-has-sommeil','f83-has-humeur')],
['Détresse et difficultés d’adaptation',p('L’entretien évalue l’humeur, les stratégies d’adaptation, l’évitement et le retentissement social.','f83-has-psychotherapie','f83-rcp-bps'),p('Une intervention psychologique structurée peut soutenir le fonctionnement, sans faire du stress une cause obligatoire.','f83-has-psychotherapie','f83-rcp-mecanismes')],
['Transmission monoaminergique ciblée par un médicament',p('L’AIPS décrit une inhibition de la recapture de sérotonine et de noradrénaline par la duloxétine ; les observations précliniques ne constituent pas un test clinique de fibromyalgie.','aips-f83-dulox-mecanisme'),p('La HAS envisage certains antidépresseurs en seconde ligne, mais l’AIPS suisse de cette spécialité ne comporte aucune indication fibromyalgie.','f83-has-antidepresseurs','aips-f83-dulox-indications')]])
t+=p('Le lien perturbation–exploration–traitement n’implique donc pas une correction moléculaire démontrée pour chaque symptôme. Le clinicien choisit une intervention sur la base de son bénéfice clinique et de sa tolérance, puis réévalue douleur, fonction et qualité de vie.','f83-has-principes-med','f83-has-suivi')
save(t)
